mapper.select:
select

from(
select

,rank() over (partition by total.CHECK_TYPE order by total.CDATE desc) rowindex
from CHB_TOTALCHECK total
left join CHB_TOTALCHECK_DETAIL detail
on detail.TOTALSEQNO = total.seqno
where 1 =1

  and DATE_FORMAT(total.CDATE,'%Y-%m-%d') <= #{searchDate,jdbcType=VARCHAR}



    #{orgCode,jdbcType=VARCHAR}


) a
where 1 = 1 limit 1
